import React, { useState } from 'react';



import { Link, useNavigate } from 'react-router-dom';



import { addToCart, toggleWishlist, getWishlist } from '../services/api';



import { isAuthenticated } from '../util/auth';



import useToast from '../hooks/useToast';



import { useCart } from '../context/CartContext';







const ProductCard = ({ product, onCartUpdate, index = 0 }) => {



  const [loading, setLoading] = useState(false);



  const [quantity, setQuantity] = useState(1);



  const [isHovered, setIsHovered] = useState(false);



  const [isWishlisted, setIsWishlisted] = useState(false);



  const [wishlistLoading, setWishlistLoading] = useState(false);



  const { showSuccessToast, showErrorToast } = useToast();



  const { updateCartCount } = useCart();



  const navigate = useNavigate();







  const handleAddToCart = async (e) => {



    e.stopPropagation();



    console.log('Add to Cart clicked!');



    console.log('Product:', product.name, 'ID:', product._id);



    console.log('Quantity:', quantity);



    console.log('Is Authenticated:', isAuthenticated());



    



    if (!isAuthenticated()) {



      console.log('User not logged in');



      window.location.href = '/cart';



      return;



    }







    try {



      console.log('Starting API call...');



      setLoading(true);



      const response = await addToCart(product._id, quantity);



      console.log('API Response:', response);



      



      if (onCartUpdate) {



        onCartUpdate();



      }



      updateCartCount();



      showSuccessToast(`${product.name} added to cart successfully!`);



    } catch (error) {



      console.error('Error in Add to Cart:', error);



      console.error('Error response:', error.response);



      console.error('Error message:', error.message);



      



      // Check if it's a network error



      if (!error.response) {



        showErrorToast('Network error. Please check your connection.');



      } else {



        showErrorToast(error.response?.data?.message || 'Error adding to cart. Please try again.');



      }



    } finally {



      setLoading(false);



    }



  };







  const getCategoryClass = (category) => {



    const classes = {



      milk: 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300',



      ghee: 'bg-amber-100 text-amber-800 dark:bg-amber-900/30 dark:text-amber-300',



      cheese: 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-300',



      butter: 'bg-orange-100 text-orange-800 dark:bg-orange-900/30 dark:text-orange-300',



      curd: 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300',



      paneer: 'bg-purple-100 text-purple-800 dark:bg-purple-900/30 dark:text-purple-300',



      cream: 'bg-pink-100 text-pink-800 dark:bg-pink-900/30 dark:text-pink-300',



      yogurt: 'bg-teal-100 text-teal-800 dark:bg-teal-900/30 dark:text-teal-300',



      lassi: 'bg-cyan-100 text-cyan-800 dark:bg-cyan-900/30 dark:text-cyan-300',



      buttermilk: 'bg-lime-100 text-lime-800 dark:bg-lime-900/30 dark:text-lime-300',



      sweets: 'bg-rose-100 text-rose-800 dark:bg-rose-900/30 dark:text-rose-300',



      cake: 'bg-fuchsia-100 text-fuchsia-800 dark:bg-fuchsia-900/30 dark:text-fuchsia-300'



    };



    return classes[category] || 'bg-gray-100 text-gray-800 dark:bg-black dark:text-gray-300';



  };







const getCategoryGradient = (category) => {
    const gradients = {
      milk: 'from-blue-200 to-blue-400 dark:from-blue-600 dark:to-blue-800',
      ghee: 'from-amber-200 to-amber-400 dark:from-amber-600 dark:to-amber-800',
      cheese: 'from-yellow-200 to-yellow-400 dark:from-yellow-600 dark:to-yellow-800',
      butter: 'from-orange-200 to-orange-400 dark:from-orange-600 dark:to-orange-800',
      curd: 'from-green-200 to-green-400 dark:from-green-600 dark:to-green-800',
      paneer: 'from-purple-200 to-purple-400 dark:from-purple-600 dark:to-purple-800',
      cream: 'from-pink-200 to-pink-400 dark:from-pink-600 dark:to-pink-800',
      yogurt: 'from-teal-200 to-teal-400 dark:from-teal-600 dark:to-teal-800',
      lassi: 'from-cyan-200 to-cyan-400 dark:from-cyan-600 dark:to-cyan-800',
      buttermilk: 'from-lime-200 to-lime-400 dark:from-lime-600 dark:to-lime-800',
      sweets: 'from-rose-200 to-pink-300 dark:from-rose-600 dark:to-pink-800',
      cake: 'from-fuchsia-200 to-pink-400 dark:from-fuchsia-600 dark:to-pink-800'
    };

    return gradients[category] || 'from-gray-200 to-gray-400 dark:from-gray-700 dark:to-gray-500';
  }; 










  // Get emoji for each category



  const getCategoryEmoji = (category) => {



    const emojis = {



      milk: '🥛',



      ghee: '🍯',



      cheese: '🧀',



      butter: '🧈',



      curd: '🥣',



      paneer: '🧊',



      cream: '🍦',



      yogurt: '🍶',



      lassi: '🥤',



      buttermilk: '🫙',



      sweets: '🍬',



      cake: '🍰'



    };



    return emojis[category] || '🥛';



  };







// Animation delay based on index for staggered entrance



  const animationDelay = `${index * 0.1}s`;







  const handleToggleWishlist = async (e) => {



    e.preventDefault();



    e.stopPropagation();



    if (!isAuthenticated()) {



      window.location.href = '/login';



      return;



    }



    try {



      setWishlistLoading(true);



      await toggleWishlist(product._id);



      setIsWishlisted(!isWishlisted);



    } catch (error) {



      console.error('Wishlist error:', error);



    } finally {



      setWishlistLoading(false);



    }



  };







  const handleCardClick = () => {



    navigate(`/product/${product._id}`);



  };







  return (



    <div 



      className="group relative overflow-visible transition-all duration-500 hover:shadow-2xl hover:shadow-primary-500/30 transform hover:scale-110 hover:z-10 rounded-[2.5rem] border-2 border-gray-200/50 dark:border-gray-700/50 hover:border-primary-500/50 bg-gradient-to-br from-white via-gray-50 to-gray-100 dark:from-gray-800 dark:via-gray-900 dark:to-black backdrop-blur-xl h-full flex flex-col cursor-pointer"



      style={{ animationDelay }}



      onMouseEnter={() => setIsHovered(true)}



      onMouseLeave={() => setIsHovered(false)}



      onClick={handleCardClick}



    >



{/* Product Image with modern effects */}



      <div className="relative h-36 overflow-hidden rounded-t-[2.3rem]">



        {/* Animated Background Gradient - pointer-events-none */}



        <div className="absolute inset-0 bg-gradient-to-br from-primary-500/10 via-transparent to-secondary-500/10 opacity-0 group-hover:opacity-100 transition-opacity duration-1000 pointer-events-none"></div>



        



        {/* Sliding Light Effect - pointer-events-none */}



        <div className="absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity duration-1000 pointer-events-none">



          <div className="absolute top-0 left-0 w-full h-1/3 bg-gradient-to-r from-transparent via-white/20 to-transparent animate-slide pointer-events-none"></div>



        </div>



        



        {product.image ? (



          <img 



            src={product.image} 



            alt={product.name}



            className={`w-full h-full object-cover transition-transform duration-1000 ${isHovered ? 'scale-110' : 'scale-100'}`}



            onError={(e) => {



              e.target.style.display = 'none';



              e.target.nextSibling.style.display = 'flex';



            }}



          />



        ) : null}



        



        {/* Fallback Image based on category */}



        <div 



          className={`w-full h-full flex items-center justify-center bg-gradient-to-br ${getCategoryGradient(product.category)} ${product.image ? 'hidden' : 'flex'}`}



        >



          <span className="text-6xl transform transition-all duration-700 group-hover:scale-110 group-hover:rotate-12">{getCategoryEmoji(product.category)}</span>



        </div>



        {/* Modern Wishlist Heart Button */}



        <button



          onClick={handleToggleWishlist}



          disabled={wishlistLoading}



          className={`absolute top-4 right-4 z-20 w-10 h-10 rounded-full flex items-center justify-center shadow-lg backdrop-blur-sm transition-all duration-300 hover:scale-110 ${



            isWishlisted 



              ? 'bg-gradient-to-br from-red-500 to-pink-500 text-white shadow-red-500/50' 



              : 'bg-white/90 dark:bg-black/90 text-gray-600 dark:text-gray-400 hover:text-red-500 dark:hover:text-red-500 shadow-gray-500/50'



          }`}



          title={isWishlisted ? 'Remove from wishlist' : 'Add to wishlist'}



        >



          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill={isWishlisted ? 'currentColor' : 'none'} viewBox="0 0 24 24" stroke="currentColor">



            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z" />



          </svg>



        </button>



      </div>







      {/* Modern Product Info */}



      <div className="p-6 relative flex flex-col h-full">



        {/* Glass Effect Overlay */}



        <div className="absolute inset-0 bg-gradient-to-br from-primary-500/5 via-transparent to-secondary-500/5 rounded-b-[2.5rem] pointer-events-none"></div>



        



        {/* Category Badge */}



        <span className={`inline-block px-3 py-1 text-xs font-bold rounded-full mb-3 ${getCategoryClass(product.category)} transform transition-all duration-300 hover:scale-105 backdrop-blur-sm relative z-10`}>



          {getCategoryEmoji(product.category)} {product.category}



        </span>







        {/* Product Name */}



        <h3 className="text-xl font-bold text-gray-800 dark:text-gray-50 mb-2 capitalize transition-all duration-300 group-hover:text-primary-600 dark:group-hover:text-primary-400 group-hover:scale-105 relative z-10">



          {product.name}



        </h3>











        {/* Price and Stock */}



        <div className="mb-4 relative z-10">



          <div className="flex items-center space-x-2 mb-2">



            <span className="text-2xl font-bold text-primary-600 dark:text-primary-400 transition-all duration-300 group-hover:scale-110">₹{product.price}</span>



            <span className="text-sm text-gray-500 dark:text-gray-400">/{product.unit}</span>



          </div>



          <div className={`text-sm font-medium px-2 py-1 rounded-full backdrop-blur-sm inline-block ${



            product.stock > 10 



              ? 'bg-green-100/80 text-green-700 dark:bg-green-900/50 dark:text-green-300' 



              : product.stock > 0 



                ? 'bg-yellow-100/80 text-yellow-700 dark:bg-yellow-900/50 dark:text-yellow-300'



                : 'bg-red-100/80 text-red-700 dark:bg-red-900/50 dark:text-red-300'



          }`}>



            {product.stock > 0 ? `Stock: ${product.stock}` : 'Out of Stock'}



          </div>



        </div>







        {/* Cart Icon and Quantity Selector */}



        <div className="flex items-center space-x-2 relative z-10 mt-auto">



          <button



            onClick={handleAddToCart}



            disabled={loading || product.stock === 0}



            title={product.stock === 0 ? 'Out of Stock' : 'Add to Cart'}



            className={`flex-shrink-0 w-12 h-12 rounded-xl transform transition-all duration-300 hover:scale-105 shadow-lg hover:shadow-xl disabled:opacity-50 disabled:cursor-not-allowed disabled:transform-none cursor-pointer backdrop-blur-sm flex items-center justify-center ${



              product.stock === 0 



                ? 'bg-gray-400 text-gray-200 cursor-not-allowed'



                : 'bg-gradient-to-r from-primary-500 to-secondary-500 text-white hover:from-primary-600 hover:to-secondary-600'



            }`}



          >



            {loading ? (



              <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div>



            ) : product.stock === 0 ? (



              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">



                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />



              </svg>



            ) : (



              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">



                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 3h2l.4 2M7 13h10l4-8H5.4M7 13L5.4 5M7 13l-2.293 2.293c-.63.63-.184 1.707.707 1.707H17m0 0a2 2 0 100 4 2 2 0 000-4zm-8 2a2 2 0 11-4 0 2 2 0 014 0z" />



              </svg>



            )}



          </button>



          



          {/* Quantity Selector */}



          <div className="flex items-center border-2 border-gray-300 dark:border-gray-600 rounded-xl overflow-hidden shadow-sm backdrop-blur-sm bg-white/50 dark:bg-black/50 flex-1" title="Select quantity">



            <button



              onClick={(e) => {



                e.stopPropagation();



                setQuantity(Math.max(1, quantity - 1));



              }}



              className="w-8 h-8 flex items-center justify-center text-gray-600 dark:text-gray-300 hover:bg-primary-500 hover:text-white transition-all duration-300 font-bold cursor-pointer"



            >



              -



            </button>



            <span className="flex-1 text-center font-bold text-gray-800 dark:text-gray-200 text-sm whitespace-nowrap">{quantity}</span>



            <button



              onClick={(e) => {



                e.stopPropagation();



                setQuantity(Math.min(product.stock, quantity + 1));



              }}



              className="w-8 h-8 flex items-center justify-center text-gray-600 dark:text-gray-300 hover:bg-primary-500 hover:text-white transition-all duration-300 font-bold cursor-pointer"



            >



              +



            </button>



          </div>



        </div>



      </div>



      



      {/* Modern Card Edge Effects - pointer-events-none so they don't block clicks */}



      <div className="absolute inset-0 rounded-[2.5rem] border-2 border-transparent group-hover:border-primary-300/50 transition-all duration-1000 pointer-events-none"></div>



      <div className="absolute inset-1 rounded-[2.5rem] border border-transparent group-hover:border-white/30 transition-all duration-1000 pointer-events-none"></div>



      



      {/* Premium Glow Effect - pointer-events-none so it doesn't block clicks */}



      <div className="absolute inset-0 bg-gradient-to-br from-primary-500/10 via-secondary-500/10 to-primary-500/10 rounded-[2.5rem] opacity-0 group-hover:opacity-100 transition-all duration-1000 blur-xl pointer-events-none"></div>



    </div>



  );



};







export default ProductCard;
